import java.util.Random;
import java.util.function.Consumer;

/**
 * Counts the comparisons and the moves (writes into the array) that bubble, selection and
 * insertion sort really make on the same data. The three sort methods have the shape of a
 * LAB211 SortService; the counters and main() only exist to measure.
 */
public class SortCost {

    // Comparisons made by the sort being measured.
    private long comparisonCount;

    // Writes into the array made by the sort being measured: a swap is 3, a shift is 1.
    private long moveCount;

    // Measures the three sorts on 200 random values, then on 200 values already in order.
    public static void main(String[] args) {
        SortCost sortCost = new SortCost();
        int[] randomArray = generateSeededArray(200, 42);
        int[] sortedArray = new int[200];

        // the same random data for all three sorts
        System.out.println("--- 200 random values ---");
        sortCost.measureSort("bubble", sortCost::sortByBubble, randomArray);
        sortCost.measureSort("selection", sortCost::sortBySelection, randomArray);
        sortCost.measureSort("insertion", sortCost::sortByInsertion, randomArray);

        // 0, 1, 2 ... 199: data that is already in order
        for (int i = 0; i < sortedArray.length; i++) {
            sortedArray[i] = i;
        }

        System.out.println("--- 200 ALREADY sorted ---");
        sortCost.measureSort("bubble", sortCost::sortByBubble, sortedArray);
        sortCost.measureSort("selection", sortCost::sortBySelection, sortedArray);
        sortCost.measureSort("insertion", sortCost::sortByInsertion, sortedArray);
    }

    // Bubble sort, ascending, in place: swaps neighbours that are in the wrong order; a pass
    // without any swap ends the sort early.
    private void sortByBubble(int[] valueArray) {
        // pass i moves the biggest remaining value to position length - 1 - i
        for (int i = 0; i < (valueArray.length - 1); i++) {
            boolean swapped = false;

            // the last i values are already in place, so stop before them
            for (int j = 0; j < (valueArray.length - 1 - i); j++) {
                comparisonCount++;

                // wrong order: swap the two neighbours (a swap is three writes)
                if (valueArray[j] > valueArray[j + 1]) {
                    int temp = valueArray[j];

                    valueArray[j] = valueArray[j + 1];
                    valueArray[j + 1] = temp;
                    moveCount += 3;
                    swapped = true;
                }
            }

            // no swap in a whole pass: the array is already sorted
            if (!swapped) {
                return;
            }
        }
    }

    // Selection sort, ascending, in place: swaps the smallest remaining value to the front;
    // it cannot stop early, sorted input or not.
    private void sortBySelection(int[] valueArray) {
        // position i receives the smallest value of valueArray[i..end]
        for (int i = 0; i < (valueArray.length - 1); i++) {
            int minIndex = i;

            // look at every value after i for a smaller one
            for (int j = i + 1; j < valueArray.length; j++) {
                comparisonCount++;

                // a smaller value: remember where it is
                if (valueArray[j] < valueArray[minIndex]) {
                    minIndex = j;
                }
            }

            // the smallest is somewhere else: swap it into position i (three writes)
            if (minIndex != i) {
                int temp = valueArray[i];

                valueArray[i] = valueArray[minIndex];
                valueArray[minIndex] = temp;
                moveCount += 3;
            }
        }
    }

    // Insertion sort, ascending, in place: shifts the bigger values right and drops each
    // value into the gap; on data already in order it barely moves.
    private void sortByInsertion(int[] valueArray) {
        // valueArray[0..i-1] is already sorted; insert valueArray[i] into it
        for (int i = 1; i < valueArray.length; i++) {
            int key = valueArray[i];
            int j = i - 1;

            // walk left while the values are bigger than key
            while (j >= 0) {
                comparisonCount++;

                // a value not bigger than key: the gap is right after it
                if (valueArray[j] <= key) {
                    break;
                }

                // a shift is ONE write
                valueArray[j + 1] = valueArray[j];
                moveCount++;
                j--;
            }

            // after the loop j is one position before the gap
            valueArray[j + 1] = key;
            moveCount++;
        }
    }

    // Makes size random values from 0 to 999; a fixed seed gives the same array every run.
    private static int[] generateSeededArray(int size, long seed) {
        Random random = new Random(seed);
        int[] valueArray = new int[size];

        // one random value per position
        for (int i = 0; i < size; i++) {
            valueArray[i] = random.nextInt(1000);
        }

        return valueArray;
    }

    // Sorts a copy of the data with one method, then prints both counters and whether the
    // result really is in order.
    private void measureSort(String name, Consumer<int[]> sortMethod, int[] dataArray) {
        int[] copyArray = dataArray.clone();
        boolean sorted = true;

        // start from zero, then sort the copy - the original stays for the next sort
        comparisonCount = 0;
        moveCount = 0;
        sortMethod.accept(copyArray);

        // any neighbour pair in the wrong order means the sort failed
        for (int i = 1; i < copyArray.length; i++) {
            // this pair is in the wrong order
            if (copyArray[i - 1] > copyArray[i]) {
                sorted = false;
            }
        }

        System.out.printf("%-10s comparisons=%-7d moves=%-7d sorted=%b%n",
                name, comparisonCount, moveCount, sorted);
    }
}

import java.util.Random;

/**
 * Doubles the input of insertion sort and counts the shifts: O(n^2) means about 4x the work
 * for 2x the data.
 */
public final class GrowthDemo {

    // Private constructor: this class only has static methods (checklist 3.4).
    private GrowthDemo() {
    }

    // Sorts 500, 1000, 2000 and 4000 random values and compares each count with the last.
    public static void main(String[] args) {
        int[] sizeArray = {500, 1000, 2000, 4000};
        long previousCount = 0;
        long shiftCount = 0;
        String ratio = "";

        // one row per size; the same seed makes every run give the same numbers
        for (int size : sizeArray) {
            shiftCount = sortByInsertion(generateSeededArray(size, 7));

            // the first row has nothing to compare with
            if (previousCount == 0) {
                ratio = "-";
            } else {
                ratio = String.format("%.2fx", ((double) shiftCount) / previousCount);
            }

            // Deliberately NOT a stopwatch: the first timed run also pays for the JVM
            // compiling the method, so timings are not reproducible. Counting operations
            // is, and a count is what you can defend.
            System.out.printf("n=%-5d insertion shifts=%-10d ratio vs previous=%s%n",
                    size, shiftCount, ratio);
            previousCount = shiftCount;
        }
    }

    // Insertion sort, ascending, in place; returns how many shifts (one write each) it made.
    private static long sortByInsertion(int[] valueArray) {
        long shiftCount = 0;

        // valueArray[0..i-1] is already sorted; insert valueArray[i] into it
        for (int i = 1; i < valueArray.length; i++) {
            int key = valueArray[i];
            int j = i - 1;

            // shift every bigger value one place to the right
            while ((j >= 0) && (valueArray[j] > key)) {
                shiftCount++;
                valueArray[j + 1] = valueArray[j];
                j--;
            }

            // after the loop j is one position before the gap
            valueArray[j + 1] = key;
        }

        return shiftCount;
    }

    // Makes size random values from 0 to 99999; a fixed seed gives the same array every run.
    private static int[] generateSeededArray(int size, long seed) {
        Random random = new Random(seed);
        int[] valueArray = new int[size];

        // one random value per position
        for (int i = 0; i < size; i++) {
            valueArray[i] = random.nextInt(100000);
        }

        return valueArray;
    }
}

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Random;

/**
 * Finds one record three ways - linear, binary, Map - and counts the steps; then shows binary
 * search failing on data that is not sorted.
 */
public class SearchCost {

    // Steps made by the search being measured.
    private long stepCount;

    // Looks for the last of 1000 ids three ways, then runs binary search on shuffled data.
    public static void main(String[] args) {
        SearchCost searchCost = new SearchCost();
        String[] idArray = new String[1000];
        String[] sortedIdArray = null;
        String[] shuffledIdArray = null;
        Map<String, Integer> indexMap = new HashMap<>();
        String target = "E0999";
        int sortedIndex = 0;
        int shuffledIndex = 0;

        // ids E0000 ... E0999; the last one is the worst case for linear search
        for (int i = 0; i < idArray.length; i++) {
            idArray[i] = String.format("E%04d", i);
        }

        // linear: one step per id until the target
        searchCost.stepCount = 0;
        searchCost.searchLinear(idArray, target);
        System.out.printf("linear steps: %d%n", searchCost.stepCount);

        // binary: sort a copy first, then halve the search part each step
        sortedIdArray = idArray.clone();
        Arrays.sort(sortedIdArray);
        searchCost.stepCount = 0;
        searchCost.searchBinary(sortedIdArray, target);
        System.out.printf("binary steps: %d%n", searchCost.stepCount);

        // Map: build the index once, then every lookup is one step
        for (int i = 0; i < idArray.length; i++) {
            indexMap.put(idArray[i], i);
        }

        System.out.printf("map lookup:   1 step, result %d%n", indexMap.get(target));

        // and the catch: the same binary search on idArray (in order) and on a shuffled copy
        sortedIndex = searchCost.searchBinary(idArray, target);
        shuffledIdArray = idArray.clone();
        Collections.shuffle(Arrays.asList(shuffledIdArray), new Random(1));
        shuffledIndex = searchCost.searchBinary(shuffledIdArray, target);
        System.out.printf("binary on sorted=%b, on shuffled=%b%n", (sortedIndex >= 0),
                (shuffledIndex >= 0));
    }

    // Linear search: compares every id from the first; returns its position or -1.
    private int searchLinear(String[] idArray, String key) {
        // one id per step, from the first to the last
        for (int i = 0; i < idArray.length; i++) {
            stepCount++;

            // found: stop at once
            if (idArray[i].equals(key)) {
                return i;
            }
        }

        return -1;
    }

    // Binary search: halves the part still to search each step; the array MUST be sorted.
    private int searchBinary(String[] sortedIdArray, String key) {
        int low = 0;
        int high = sortedIdArray.length - 1;

        // search while the part [low, high] still holds at least one id
        while (low <= high) {
            int middle = low + ((high - low) / 2);
            int compareResult = sortedIdArray[middle].compareTo(key);

            stepCount++;

            // found: the middle id is the key
            if (compareResult == 0) {
                return middle;
            }

            // middle id smaller: the key can only be on the right, else only on the left
            if (compareResult < 0) {
                low = middle + 1;
            } else {
                high = middle - 1;
            }
        }

        return -1;
    }
}

import java.util.Arrays;

/**
 * The off-by-one bug in bubble sort, and proof that it is wrong: sortByBubbleBroken is the
 * DELIBERATE mistake, sortByBubble is the one to copy.
 */
public final class OffByOne {

    // Private constructor: this class only has static methods (checklist 3.4).
    private OffByOne() {
    }

    // WRONG, on purpose: the outer loop stops one pass too early.
    private static void sortByBubbleBroken(int[] valueArray) {
        // THE BUG: (length - 2) where it must be (length - 1)
        for (int i = 0; i < (valueArray.length - 2); i++) {
            // the last i values are already in place, so stop before them
            for (int j = 0; j < (valueArray.length - 1 - i); j++) {
                // wrong order: swap the two neighbours
                if (valueArray[j] > valueArray[j + 1]) {
                    int temp = valueArray[j];

                    valueArray[j] = valueArray[j + 1];
                    valueArray[j + 1] = temp;
                }
            }
        }
    }

    // Correct bubble sort: length - 1 passes, each stopping before the sorted tail.
    private static void sortByBubble(int[] valueArray) {
        // pass i moves the biggest remaining value to position length - 1 - i
        for (int i = 0; i < (valueArray.length - 1); i++) {
            // the last i values are already in place, so stop before them
            for (int j = 0; j < (valueArray.length - 1 - i); j++) {
                // wrong order: swap the two neighbours
                if (valueArray[j] > valueArray[j + 1]) {
                    int temp = valueArray[j];

                    valueArray[j] = valueArray[j + 1];
                    valueArray[j + 1] = temp;
                }
            }
        }
    }

    // Tells whether every value is not bigger than the one after it.
    private static boolean isSorted(int[] valueArray) {
        // one neighbour pair in the wrong order is enough to say no
        for (int i = 1; i < valueArray.length; i++) {
            // this pair is in the wrong order: stop at once
            if (valueArray[i - 1] > valueArray[i]) {
                return false;
            }
        }

        return true;
    }

    // Runs both versions on reversed data, then the broken one on nearly sorted data.
    public static void main(String[] args) {
        int[] hardArray = {5, 4, 3, 2, 1};
        int[] easyArray = {1, 2, 3, 5, 4};
        int[] brokenArray = hardArray.clone();
        int[] correctArray = hardArray.clone();

        // fully reversed data: the broken version is caught
        sortByBubbleBroken(brokenArray);
        sortByBubble(correctArray);
        System.out.printf("broken:  %s sorted=%b%n", Arrays.toString(brokenArray),
                isSorted(brokenArray));
        System.out.printf("correct: %s sorted=%b%n", Arrays.toString(correctArray),
                isSorted(correctArray));

        // nearly sorted data: the same bug gives the right answer and hides
        sortByBubbleBroken(easyArray);
        System.out.printf("broken on easy data: %s sorted=%b%n", Arrays.toString(easyArray),
                isSorted(easyArray));
    }
}
